		public static string[] Of(string kind)
		{
			if (kind == null)
			{
				return null;
			}
			if (!_sets.TryGetValue(kind, out var value))
			{
				return null;
			}
			return value;
		}

		public static string KindOf(string eventPath)
		{
			if (eventPath == null || !eventPath.StartsWith("event:/SFX/UNITS/", StringComparison.Ordinal) || !eventPath.EndsWith("/idle", StringComparison.Ordinal))
			{
				return null;
			}
			return eventPath.Substring("event:/SFX/UNITS/".Length, eventPath.Length - "event:/SFX/UNITS/".Length - "/idle".Length);
		}
	}
